import{_ as a,o as n,c as e,ai as p}from"./chunks/framework.ampVZV4B.js";const o=JSON.parse('{"title":"Prompt 怎么写才像工程","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/basics/prompt-engineering.md","filePath":"ai/dev/basics/prompt-engineering.md"}'),l={name:"ai/dev/basics/prompt-engineering.md"};function i(r,s,t,c,b,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="prompt-怎么写才像工程" tabindex="-1">Prompt 怎么写才像工程 <a class="header-anchor" href="#prompt-怎么写才像工程" aria-label="Permalink to “Prompt 怎么写才像工程”">​</a></h1><blockquote><p>打开这篇 → 套最小结构 → 复制模板 → 丢给 AI。先别背一百个技巧。</p></blockquote><p>核心原则：</p><blockquote><p><strong>工程里够用的 Prompt，不是文采好，而是结构稳、约束清、输出可复用。</strong></p></blockquote><hr><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h2><p>适合用「工程化 Prompt」的时候：</p><ul><li>同一类任务要反复做（总结、Review、改 Bug、写测试）</li><li>输出格式必须稳定（表格、JSON、固定章节）</li><li>需要限制 AI 别乱改、别编造、别扩 scope</li><li>要把一次好用的问法沉淀成模板，给自己或团队复用</li></ul><p>不适合：随口问一句、一次性探索。那种场景随便聊就行，不必硬套模板。</p><hr><h2 id="最小结构-背下来" tabindex="-1">最小结构（背下来） <a class="header-anchor" href="#最小结构-背下来" aria-label="Permalink to “最小结构（背下来）”">​</a></h2><p>记住这几块就够用。日常四块；工程场景再补上下文和示例。</p><table tabindex="0"><thead><tr><th>块</th><th>作用</th><th>一句话</th></tr></thead><tbody><tr><td>角色</td><td>设定视角</td><td>你希望模型扮演谁</td></tr><tr><td>任务</td><td>说清目标</td><td>要它完成什么</td></tr><tr><td>约束</td><td>画边界</td><td>不能做什么、不要编造、不要扩 scope</td></tr><tr><td>输出格式</td><td>强约束结果形态</td><td>必须按什么结构输出</td></tr><tr><td>上下文（常用）</td><td>提供材料</td><td>Diff、报错、业务规则、相关代码</td></tr><tr><td>示例（可选）</td><td>校准风格与粒度</td><td>给 1 个正例，必要时再给反例</td></tr></tbody></table><p>最小可跑版本：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>角色：……</span></span>
<span class="line"><span>任务：……</span></span>
<span class="line"><span>约束：……</span></span>
<span class="line"><span>输出格式：……</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[材料 / 上下文]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>工程增强版再加：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>上下文：……</span></span>
<span class="line"><span>示例：……</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h2 id="使用前准备" tabindex="-1">使用前准备 <a class="header-anchor" href="#使用前准备" aria-label="Permalink to “使用前准备”">​</a></h2><p>写 Prompt 前先想清楚三件事：</p><ol><li><strong>这次任务的验收标准是什么？</strong>（什么叫「做完了」）</li><li><strong>必须提供哪些材料？</strong>（缺上下文就只能得到泛泛回答）</li><li><strong>输出要拿去干什么？</strong>（给人读、直接粘贴、还是再交给下一步 AI）</li></ol><p>材料尽量具体：代码 Diff、报错原文、接口定义、业务规则、已知限制。不要只丢一句「帮我看看这段代码」。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><h3 id="_1-先定结构-再堆技巧" tabindex="-1">1. 先定结构，再堆技巧 <a class="header-anchor" href="#_1-先定结构-再堆技巧" aria-label="Permalink to “1. 先定结构，再堆技巧”">​</a></h3><p>「像工程」靠的是可复用结构，不是措辞花哨。角色、任务、约束、输出格式齐全，通常比堆形容词更稳。</p><h3 id="_2-约束写清楚-比多说「请认真」有用" tabindex="-1">2. 约束写清楚，比多说「请认真」有用 <a class="header-anchor" href="#_2-约束写清楚-比多说「请认真」有用" aria-label="Permalink to “2. 约束写清楚，比多说「请认真」有用”">​</a></h3><p>优先写：</p><ul><li>不要修改代码 / 不要重构无关部分</li><li>不确定就标「需要确认」，不要编造</li><li>只输出指定格式，不要开场白和结尾客气话</li></ul><h3 id="_3-输出格式是稳定性的关键" tabindex="-1">3. 输出格式是稳定性的关键 <a class="header-anchor" href="#_3-输出格式是稳定性的关键" aria-label="Permalink to “3. 输出格式是稳定性的关键”">​</a></h3><p>让模型按你要的格式输出，不要让它自由发挥。常用约束：</p><ul><li>必须用 Markdown / JSON</li><li>必须包含：结论 / 依据 / 风险 / 下一步</li><li>每条不超过 N 行</li><li>没有发现问题时直接说明，不要硬凑问题</li></ul><h3 id="_4-一次只做一类事" tabindex="-1">4. 一次只做一类事 <a class="header-anchor" href="#_4-一次只做一类事" aria-label="Permalink to “4. 一次只做一类事”">​</a></h3><p>把「分析」和「修改」、「总结」和「扩写」拆开。混在一个 Prompt 里，最容易越改越大。</p><hr><h2 id="可直接复制-通用模板" tabindex="-1">可直接复制：通用模板 <a class="header-anchor" href="#可直接复制-通用模板" aria-label="Permalink to “可直接复制：通用模板”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>角色：你是一名资深工程师，负责[场景]。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>任务：</span></span>
<span class="line"><span>[用一句话说清要完成什么]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>上下文：</span></span>
<span class="line"><span>[粘贴 Diff / 报错 / 需求 / 相关代码]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 只处理上述任务，不扩展范围</span></span>
<span class="line"><span>- 不确定的地方明确标「需要确认」</span></span>
<span class="line"><span>- 不要编造不存在的业务规则或 API</span></span>
<span class="line"><span>- 不要直接修改代码（若本轮只要分析）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出格式：</span></span>
<span class="line"><span>1. 结论（3 行内）</span></span>
<span class="line"><span>2. 关键发现（按严重程度）</span></span>
<span class="line"><span>3. 建议下一步（可执行）</span></span>
<span class="line"><span>4. 需要我补充的信息（若有）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><hr><h2 id="三个常见场景套用" tabindex="-1">三个常见场景套用 <a class="header-anchor" href="#三个常见场景套用" aria-label="Permalink to “三个常见场景套用”">​</a></h2><h3 id="_1-技术总结" tabindex="-1">1）技术总结 <a class="header-anchor" href="#_1-技术总结" aria-label="Permalink to “1）技术总结”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>角色：技术文档编辑</span></span>
<span class="line"><span>任务：把下面材料总结成可复用笔记</span></span>
<span class="line"><span>约束：不编造材料里没有的内容；不确定标出来</span></span>
<span class="line"><span>输出格式：</span></span>
<span class="line"><span>## 要点（5 条内）</span></span>
<span class="line"><span>## 例子（1～2 个）</span></span>
<span class="line"><span>## 常见坑（1～2 个）</span></span>
<span class="line"><span>## 我还需要确认什么</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_2-code-review-只找问题" tabindex="-1">2）Code Review（只找问题） <a class="header-anchor" href="#_2-code-review-只找问题" aria-label="Permalink to “2）Code Review（只找问题）”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>角色：Code Reviewer</span></span>
<span class="line"><span>任务：对下面 Diff 做问题优先的 Review，不要改代码</span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 优先找本次修改引入的问题</span></span>
<span class="line"><span>- 不为风格差异提意见</span></span>
<span class="line"><span>- 不确定标「需要确认」</span></span>
<span class="line"><span>输出格式：严重问题 / 一般问题 / 可优化项 / Review 结论</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_3-改-bug-先方案后动手" tabindex="-1">3）改 Bug（先方案后动手） <a class="header-anchor" href="#_3-改-bug-先方案后动手" aria-label="Permalink to “3）改 Bug（先方案后动手）”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>角色：负责定位与修复的工程师</span></span>
<span class="line"><span>任务：根据报错和相关代码定位根因，先给最小修复方案</span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 本轮不要直接改代码</span></span>
<span class="line"><span>- 不进行无关重构</span></span>
<span class="line"><span>- 说明可能副作用</span></span>
<span class="line"><span>输出格式：</span></span>
<span class="line"><span>1. 根因判断</span></span>
<span class="line"><span>2. 依据</span></span>
<span class="line"><span>3. 最小修改方案</span></span>
<span class="line"><span>4. 风险与验证方式</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>更完整的 Review 工作流见 <a href="/my-vitepress-site/ai/dev/coding/ai-code-review.html">用 AI 做 Code Review</a>。</p><hr><h2 id="迭代方式-像调代码一样调-prompt" tabindex="-1">迭代方式（像调代码一样调 Prompt） <a class="header-anchor" href="#迭代方式-像调代码一样调-prompt" aria-label="Permalink to “迭代方式（像调代码一样调 Prompt）”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>跑一次</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>看输出哪里不稳 / 跑偏</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>只改一处：补约束 或 收紧输出格式 或 补上下文</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>再跑，对比差异</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>不要一次改五处。和改代码一样：单变量调试，才知道哪句 Prompt 生效。</p><hr><h2 id="使用后的人工检查" tabindex="-1">使用后的人工检查 <a class="header-anchor" href="#使用后的人工检查" aria-label="Permalink to “使用后的人工检查”">​</a></h2><p>拿到输出后，人至少看：</p><ul><li>有没有编造材料里不存在的事实</li><li>有没有超出任务范围（顺手重构、扩需求）</li><li>格式是否可直接复用；若不能，把格式约束再写死一轮</li><li>不确定项是否已标出，还是被写成了肯定结论</li></ul><hr><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to “我的判断”">​</a></h2><p>Prompt「像工程」，靠的不是技巧清单，而是：</p><blockquote><p><strong>最小结构固定 + 约束清晰 + 输出可验收 + 能沉淀成模板。</strong></p></blockquote><p>日常记住四块：<strong>角色 · 任务 · 约束 · 输出格式</strong>；缺上下文就补材料，要风格稳定再加示例。够用了再谈高级技巧。</p>`,59)])])}const u=a(l,[["render",i]]);export{o as __pageData,u as default};
